/**
 * Firma manuscrita oficial de Carlos Alberto Prost (WolfTeI)
 * Trazo con fondo transparente 100% y tinta azul estilográfica.
 */
export const FIRMA_OFICIAL_CARLOS_BASE64 = 'data:image/png;base64,';

/**
 * Obtiene la firma activa a estampar en documentos (prioriza personalizada en localStorage o la oficial por defecto)
 */
export function obtenerFirmaActiva(): string {
  if (typeof window !== 'undefined') {
    const custom = localStorage.getItem('wolftei_firma_carlos');
    if (custom && custom.startsWith('data:image')) {
      return custom;
    }
  }
  return FIRMA_OFICIAL_CARLOS_BASE64;
}
